/**
 * fixture 构建期内嵌资源 —— 由开发机一次性脚本生成后随源码提交。
 * 运行时零下载、零 CDN：Web 与原生均从这些 base64 常量同步解码。
 *
 * 生成来源（真实资源，非伪造）：
 *   - FIXTURE_FONT_BASE64：系统 Liberation Sans（SIL Open Font License 1.1，
 *     /usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf）经 fontTools
 *     pyftsubset 子集化为可见 ASCII（U+0020-007E），族名改写为 "FixtureSans"。
 *     已用 canvaskit-wasm@0.41.0 在 Node 中验证：MakeFreeTypeFaceFromData 成功、
 *     "Skia Text 123" 全部 13 个 glyph 宽度非零。
 *   - FIXTURE_IMAGE_BASE64：脚本以 zlib 手工编码的 96x64 RGBA PNG（渐变底 +
 *     白色边框 + 深色对角线 + 实心圆标记），已用同一 CanvasKit 验证
 *     MakeImageFromEncoded 解码为 96x64。
 */

/** Skia 文本对象使用的字体族名（与 registerFont 注册名一致） */
export const FIXTURE_FONT_FAMILY = 'FixtureSans';

/**
 * Web CanvasKit shaping 用的注册名。它们是注册到同一个 TypefaceFontProvider 的名字，
 * 绝不能替换为字体文件中的内部 family 名，以免 Web FreeType fallback 变成环境相关行为。
 *
 * 来源均为系统 Noto 的 SIL Open Font License 1.1 版本，经本地 fontTools `pyftsubset`
 * 只保留 fixture 所需字符（并移除 hint/DSIG）。emoji 是 Noto Color Emoji 位图字体：
 * CanvasKit FreeType 是否能够接受它必须由 Web fixture 在运行时如实报告。
 */
export const FIXTURE_SHAPING_LATIN_FONT_FAMILY = 'FixtureShapingLatin';
export const FIXTURE_SHAPING_CJK_FONT_FAMILY = 'FixtureShapingCjk';
export const FIXTURE_SHAPING_ARABIC_FONT_FAMILY = 'FixtureShapingArabic';
export const FIXTURE_SHAPING_EMOJI_FONT_FAMILY = 'FixtureShapingEmoji';
